"""闭区间二分查找练习：保留函数接口，逐个完成 TODO。"""


def binary_search(data, target):
    # TODO 1: 设置闭区间的左右端点
    left = None
    right = None

    # TODO 2: 写出闭区间仍然有效的循环条件
    while False:
        # TODO 3: 计算当前区间的中点
        mid = None

        if data[mid] == target:
            return mid
        if data[mid] < target:
            # TODO 4: 排除 mid 及其左侧
            left = None
        else:
            # TODO 5: 排除 mid 及其右侧
            right = None

    return -1


if __name__ == "__main__":
    samples = [3, 8, 12, 17, 21, 29, 34, 40]
